  ],
  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "DECISION-JUSTIFIED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Architecture and normative execution sections explain provider-owned state, separate cloud lifecycle, exact AWS Change Set execution and Azure preview limitations. ADR 0036 Alternatives explains rejection of a generic engine and prompt-based authorization."
    },
    {
      "id": "OPEN-QUESTIONS-RESOLVABLE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "design.md Open Questions OQ-002 states 'Blocks Implementation: yes' and names the development environment owner, but provides no 'Resolution Path:' identifying the concrete action that resolves review-host readiness. Connectivity and availability statements do not specify the remaining resolution procedure; 'until the required repository reviews pass' supplies an outcome rather than an actionable path. Add the required resolution field and concrete host/review action so the blocking prerequisite is implementable. OQ-001 also lacks the literal Resolution Path field, although its supply-input instructions provide a substantive nonblocking path."
    },
    {
      "id": "ASSUMPTIONS-VALID",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Assumptions treats protected environments and exclusive write ownership as externally configured prerequisites, not established facts. requirements.md Assumptions selects GitHub Actions; infra-spec.md CI/CD Sequence and security-spec.md Authentication Flow define the corresponding enforcement basis."
    },
    {
      "id": "NO-REQ-CONTRADICTION",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Constraint Compliance addresses thin integration, single execution ownership, legacy compatibility, authorization, genuine observations, historical preservation, account/region allowlists, evidence residency/retention and backup prerequisites. Normative lifecycle and release sections preserve the remaining no-retry, no-import, no-production-write and immutable-tag constraints."
    },
    {
      "id": "PERF-ADDRESSED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "No numeric latency, throughput or availability SLA appears in requirements.md. Its concurrency and timeout requirements are addressed by design.md lifecycle serialization and read-only UNKNOWN recovery, with TEST-006; infra-spec.md Service Level Objectives requires bounded polling."
    },
    {
      "id": "DEPLOYMENT-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Deployment / CI Plan specifies existing plugin packaging, deterministic credential-free CI and opt-in protected sandbox jobs. infra-spec.md CI/CD Sequence supplies validation, prepare, approval, lock, execution and observation ordering. No database schema deployment or incremental feature-flag rollout is proposed."
    },
    {
      "id": "MIGRATION-PLANNED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Data Plan introduces file-backed versioned contracts rather than database tables or columns. Its Migration Strategy preserves existing-version dispatch and evidence readability while allowlisting new profiles; database migration naming, rollback and row-volume requirements do not apply."
    },
    {
      "id": "INTEGRATION-IDENTIFIED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md External Integration Inventory lists GitHub API 2022-11-28, ARM API 2025-04-01, CloudFormation API 2010-05-15, authoring toolchains, upstream skills and optional planning MCP, with contracts and fail-closed behavior. Exact tool patches must be compatibility-tested and locked before use."
    },
    {
      "id": "DESIGN-WITHIN-SCOPE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md routing, authorization, lifecycle, observation, #423 repair, public invocation and documentation/release sections cover REQ-001–014. The two provider adapters, shared validation and examples match the initial scope; frontend-spec.md and Design System Compliance explicitly exclude new graphical infrastructure."
    },
    {
      "id": "VERIFICATION-PATH-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Test Strategy and Unit and Integration Boundaries name four deterministic suite entry points, TEST-004/005 authorization and mutation checks, TEST-006 reconciliation/dependency failure, TEST-009 unhealthy/no-change cases and TEST-010 evidence attacks. Isolated host and separately authorized live sandbox evidence are explicitly distinguished."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Minor",
      "finding": "SKIP: no domain/ directory, as supplied by the host and corroborated by investigation.md Reverification."
    }
  ]
}
